* @return DataResponse<Http::STATUS_OK|Http::STATUS_CREATED, array{id: int, name: string}, array{}>
*/
public function someControllerMethod() {
... if (...) {
return new DataResponse(["id" => $id, "name" => $name], Http::STATUS_OK);
} else {
