namespace OCA\YourAppName\DAV;

class CalendarObject implements \Sabre\CalDAV\ICalendarObject, \Sabre\DAVACL\IACL {
 /** @var Calendar */
 private $calendar;
 /** @var string */
 private $name;

 /**
 * CalendarObject constructor.

