# Projects

Projects are a way to link items from different apps via a common interface. App developers can integrate into projects and provide their own entity types to link with. ## Register a resource provider

Things like files, deck cards and talk rooms are called Resources in projects. In order to add your own resource type, we need to create a class implementing the
`OCPCollaborationResourcesIProvider` interface. ```
<?php

namespace OCA\MyApp\Collaboration\Resources;

use OCP\Collaboration\Resources\IProvider;
use OCP\Collaboration\Resources\IResource;
use OCP\IURLGenerator;
use OCP\IUser;

class MyResourceProvider implements IProvider {
 public const RESOURCE_TYPE = 'my-app-item';

 /**
 * @var IURLGenerator
 */
 private $url;

 public function __construct(IURLGenerator $url) {
 $this->url = $url;
 }

 /**
 * @inheritDoc
 */
 public function getType(): string {
 return self::RESOURCE_TYPE;
 }

 /**
 * @inheritDoc
 */
 public function getResourceRichObject(IResource $resource): array {
 $item = $this->getItem($resource);
 $icon = $this->url->linkToRouteAbsolute('myapp.images.get_icon', ['id' => $item->getId()]);
 $resourceUrl = $this->url->linkToRouteAbsolute('bookmarks.page.index', ['item' => $bookmark->getId()]);

 return [
 'type' => self::RESOURCE_TYPE,
 'id' => $resource->getId(),
 'name' => $item->getTitle(),
 'link' => $resourceUrl,
 'iconUrl' => $icon,
 ];
 }

 /**
 * @inheritDoc
 */
 public function canAccessResource(IResource $resource, ?IUser $user): bool {
 if ($resource->getType() !== self::RESOURCE_TYPE || !($user instanceof IUser)) {
 return false;
 }
 $bookmark = $this->getItem($resource);
 if ($bookmark === null) {
 return false;
 }
 return $bookmark->getUserId() === $user->getUID()
 }

 private function getItem(IResource $resource) : ?Item {
 // implement me
 }
}
```
