 ) {
 }

 public function getName(): string {
 return $this->l->t('My awesome speech to text provider');
 }

 public function setUserId(?string $userId): void {
 $this->userId = $userId;
 }

 public function transcribeFile(File $file): string {
 // transcribe file here with the use of $this->userId context and return transcript
 }
}
```
## Provider registration

The provider class is registered via the bootstrap mechanism of the `Application` class. ```
:emphasize-lines: 16

<?php

declare(strict_types=1);

namespace OCA\MyApp\AppInfo;

use OCA\MyApp\SpeechToText\Provider;
use OCP\AppFramework\App;
use OCP\AppFramework\Bootstrap\IBootContext;
use OCP\AppFramework\Bootstrap\IBootstrap;
use OCP\AppFramework\Bootstrap\IRegistrationContext;

class Application extends App implements IBootstrap {

 public function register(IRegistrationContext $context): void {
 $context->registerSpeechToTextProvider(Provider::class);
 }

 public function boot(IBootContext $context): void {}

}
```

# User Status

Nextcloud allows user to publish their current status. The status is then
available in various part of the user interface (e.g. participants list in
a Talk room).

## Query Status

Using the `OCPUserStatusIManager` interface, it is possible to query
the user status, for a group of users.

```
<?php

namespace OCA\MyGreatApp\Service;

use OCP\UserStatus\IManager as IStatusManager;
use OCP\UserStatus\IUserStatus;

class MyService {
 /** @var IStatusManager $statusManager */
 public $statusManager;

 public function __construct(IStatusManager $statusManager) {
 $this->statusManager = $statusManager;
 }

 /**
 * @param string[] $userIds
 * @return IUserStatus[]
 */
 public function queryStatusForUsers(array $userIds): array {
 return $this->statusManager->getUserStatuses($userIds);
 }
}
```
## Updating the status programmatically

A Nextcloud application can change the user status programmatically. This feature
`setUserStatus` from the `OCPUserStatusIManager` interface when for example a
user executes an action in the UI.

If the status is supposed to be reverted with an upcoming action from the
user, `setUserStatus` will require to be called with `$createBackup = true`.

This then can be reverted with a call to `revertUserStatus` with the same
`$messageId` and `$status`.

```
<?php

namespace OCA\MyGreatApp\Status;

use OCA\MyGreatApp\MyEvents;
use OCA\MyGreatApp\CoolStartEvent;
use OCA\MyGreatApp\CoolEndEvent;
use OCP\UserStatus\IManager as IStatusManager;
use OCP\UserStatus\IUserStatus;

class Listener {
 /** @var IStatusManager $statusManager */
 public $statusManager;

 public function __construct(IStatusManager $statusManager) {
 $this->statusManager = $statusManager;
 }

 public static function register(IEventDispatcher $dispatcher): void {
 $dispatcher->addListener(MyEvents::COOL_EVENT_STARTED, static function (CoolStartEvent $event) {
 /** @var self $listener */
 $listener = \OC::$server->get(self::class);
 $listener->setUserStatus($event);
 });

 $dispatcher->addListener(MyEvents::COOL_EVENT_FINISHED, static function (CoolEndEvent $event) {
 /** @var self $listener */
 $listener = \OC::$server->get(self::class);
 $listener->revertUserStatus($event);
 });
 }

 public function setUserStatus(ModifyParticipantEvent $event): void {
 $this->statusManager->setUserStatus($event->getUserId(), 'meeting', IUserStatus::AWAY, true);
 }

 public function revertUserStatus(ModifyParticipantEvent $event): void {
 $this->statusManager->revertUserStatus($event->getUserId(), 'meeting', IUserStatus::AWAY);
 }
```

# Talk Integration

Nextcloud Talk (https://apps.nextcloud.com/apps/spreed) is the chat, video and audio conferencing solution in Nextcloud. Apps can access Talk capabilities through a public API.

All communication from an app to the Talk backend is handled through a *broker* `OCPTalkIBroker`. Inject the Talk broker into your class to make use of it.

## Check for Talk existence

Talk is an optional app. It has to be installed and enable to be used.

```
<?php

/** @var \OCP\Talk\IBroker $broker */
if ($broker->hasBackend()) {
 // Do something with it
} else {
 // Hide Talk integration from a user or use other communication channels, if applicable
}
```
## Create a conversation

A new conversation needs a name and at least one moderator. By default this conversation will be private.

```
<?php

/** @var \OCP\Talk\IBroker $broker */
/** @var \OCP\IUser $alice */
/** @var \OCP\IUser $bob */
$conversation = $broker->createConversation(
 'Weekly 1:1',
 [$alice, $bob]
);
```
### Customize the conversation

It's possible to adjust the defaults:

- `setPublic`: Make the conversation public (allowing anyone with the link to access the conversation).
- `setMeetingDate` (since Nextcloud 32.0.9, 33.0.3 and 34.0.0): Mark a conversation as related to a meeting.
 This will make Talk automatically expire the conversation 4 weeks (value is configurable)
 after the meeting, unless the owner confirms the conversation should remain.

```
<?php

/** @var \OCP\Talk\IBroker $broker */
/** @var \OCP\IUser $alice */
/** @var \OCP\IUser $bob */
$options = $broker->newConversationOptions();
$options->setPublic();
$options->setMeetingDate(
 $this->timeFactory->getDateTime(new \DateTime('2026-04-07 13:00')),
 $this->timeFactory->getDateTime(new \DateTime('2026-04-07 14:00')),
);

$conversation = $broker->createConversation(
 'Weekly 1:1',
 [$alice, $bob],
 $options
);
```
## Delete a conversation

A conversation can be deleted by id (token).

```
<?php

/** @var \OCP\Talk\IBroker $broker */
$broker->deleteConversation('abc123');
```

